// The support file generated Ruby requires (docs/more-languages.md, "Ruby"): the semantics' number
// formatting and conversions, event dispatchers and the latent queue. A copy sits next to every
// generated file (a companion file); each copy reopens the one module Vg, so they share its state.
export const RUBY_RUNTIME_FILE = 'vgraph_runtime.rb';

export function rubyRuntime(): string {
  return `${RUBY_RUNTIME}\n`;
}

const RUBY_RUNTIME = String.raw`# frozen_string_literal: true

# Support code for Ruby generated by Blueprint Visual Scripting (docs/more-languages.md).
# Generated files require it with require_relative. Do not edit (@generated): it is rewritten when graphs are compiled.
# rubocop:disable all
require "json"
require "set"

module Vg
  # ---- Event dispatchers -------------------------------------------------------------------------
  # Bound events (an object and its method's name) run in the order they were bound, each once.
  class Dispatcher
    def initialize
      @handlers = []
    end

    def bind(object, method)
      @handlers << [object, method] unless @handlers.any? { |o, m| o.equal?(object) && m == method }
    end

    def unbind(object, method)
      index = @handlers.index { |o, m| o.equal?(object) && m == method }
      @handlers.delete_at(index) if index
    end

    def clear
      @handlers.clear
    end

    def broadcast(*args)
      @handlers.dup.each { |object, method| object.send(method, *args) }
    end
  end

  # ---- Latent actions ----------------------------------------------------------------------------
  # Delay's actions, of every class, run from one queue in the order they fall due, once Start (and
  # Main) have returned.
  @pending ||= []
  @order ||= 0

  def self.now
    Process.clock_gettime(Process::CLOCK_MONOTONIC)
  end

  def self.delay(seconds, &action)
    @order += 1
    @pending << { due: now + [0.0, seconds.to_f].max, order: @order, action: action }
  end

  # An async method's Thread (docs/node-authoring.md, gap 4): once it has finished, its Completed
  # joins the queue with the thread's value. An exception in it stops the run.
  @waiting ||= []

  def self.await_latent(thread, &completed)
    thread.report_on_exception = false
    @waiting << [thread, completed]
  end

  def self.run_latent_actions
    until @pending.empty? && @waiting.empty?
      finished, @waiting = @waiting.partition { |thread, _| !thread.alive? }
      finished.each do |thread, completed|
        value = thread.value
        delay(0) { completed.call(value) }
      end
      if @pending.empty?
        sleep(0.001)
        next
      end
      @pending.sort_by! { |entry| [entry[:due], entry[:order]] }
      wait = @pending.first[:due] - now
      if wait > 0
        # While threads run, look at them again soon.
        sleep(@waiting.empty? ? wait : [wait, 0.001].min)
        next
      end
      @pending.shift[:action].call
    end
  end

  def self.reset
    @pending.clear
    @waiting.clear
  end

  # ---- Values (docs/semantics.md) ----------------------------------------------------------------

  # Numbers as text by JavaScript's rules: Ruby's shortest digits, laid out as JavaScript does.
  def self.format_number(x)
    return x.to_s if x.is_a?(Integer)
    return "NaN" if x.nan?
    return (x > 0 ? "Infinity" : "-Infinity") if x.infinite?
    return "0" if x.zero?
    sign = x < 0 ? "-" : ""
    mantissa, exponent = x.abs.to_s.split("e")
    whole, fraction = mantissa.split(".")
    all = whole + (fraction || "")
    digits = all.sub(/\A0+/, "")
    point = whole.length + exponent.to_i - (all.length - digits.length)
    digits = digits.sub(/0+\z/, "")
    return sign + digits + "0" * (point - digits.length) if digits.length <= point && point <= 21
    return sign + digits[0, point] + "." + digits[point..] if point > 0 && point <= 21
    return sign + "0." + "0" * -point + digits if point > -6 && point <= 0
    rest = digits.length > 1 ? "." + digits[1..] : ""
    sign + digits[0] + rest + "e" + (point > 0 ? "+" : "-") + (point - 1).abs.to_s
  end

  def self.key_text(key)
    key.is_a?(String) ? key : format(key)
  end

  # Containers and structs print as JSON: sets in ascending order, hashes in the order keys were added.
  # Values in the semantics' order. Ruby's booleans don't compare, so they sort as 0 and 1.
  def self.sorted(values)
    values.sort_by { |item| item == true ? 1 : (item == false ? 0 : item) }
  end

  def self.json(value)
    case value
    when nil then "null"
    when true then "true"
    when false then "false"
    when Integer then value.to_s
    when Float then value.nan? || value.infinite? ? "null" : format_number(value)
    when String then JSON.generate(value)
    when Array then "[" + value.map { |item| json(item) }.join(",") + "]"
    when Set then json(sorted(value.to_a))
    when Hash then "{" + value.map { |key, item| JSON.generate(key_text(key)) + ":" + json(item) }.join(",") + "}"
    else
      if value.respond_to?(:vg_fields)
        "{" + value.vg_fields.map { |name, item| JSON.generate(name) + ":" + json(item) }.join(",") + "}"
      else
        JSON.generate(value.class.name.to_s)
      end
    end
  end

  def self.format(value)
    case value
    when nil then ""
    when true then "true"
    when false then "false"
    when Integer, Float then format_number(value)
    when String then value
    else json(value)
    end
  end

  # Text as a number, as JavaScript's Number() reads it: blank is 0, anything else not a number NaN.
  def self.to_number(value)
    case value
    when nil then 0.0
    when true then 1.0
    when false then 0.0
    when Numeric then value
    when String
      text = value.strip
      return 0.0 if text.empty?
      return Float::INFINITY if text == "Infinity" || text == "+Infinity"
      return -Float::INFINITY if text == "-Infinity"
      return text.to_i(16).to_f if text.match?(/\A0[xX]\h+\z/)
      text.match?(/\A[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?\z/) ? text.to_f : Float::NAN
    else Float::NAN
    end
  end

  # Truth as the semantics define it: false, nil, 0, NaN and empty text are false.
  def self.to_boolean(value)
    case value
    when nil, false then false
    when Integer then value != 0
    when Float then value != 0 && !value.nan?
    when String then !value.empty?
    else true
    end
  end
end`;
